-- Minimal structural fixture based on the audited legacy column types.
-- In particular views_primeras_3h starts as PostgreSQL integer (int4), exactly
-- as observed in the current table, so the candidate migration must widen it.
DO $roles$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon') THEN
        CREATE ROLE anon NOLOGIN;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated') THEN
        CREATE ROLE authenticated NOLOGIN;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'service_role') THEN
        CREATE ROLE service_role NOLOGIN BYPASSRLS;
    END IF;
END
$roles$;

CREATE SCHEMA IF NOT EXISTS pr_d_test;
CREATE TABLE pr_d_test.youtube_shorts_log (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    youtube_video_id text NOT NULL,
    views_primeras_3h integer,
    created_at timestamptz DEFAULT now(),
    updated_at timestamptz DEFAULT now()
);

-- Seed a legacy row before applying the candidate migration and its write guard.
INSERT INTO pr_d_test.youtube_shorts_log (youtube_video_id, views_primeras_3h)
VALUES ('legacy-fixture', 123);

GRANT USAGE ON SCHEMA pr_d_test TO anon, authenticated, service_role;
ALTER TABLE pr_d_test.youtube_shorts_log ENABLE ROW LEVEL SECURITY;
GRANT ALL PRIVILEGES ON TABLE pr_d_test.youtube_shorts_log TO anon, authenticated, service_role;
GRANT USAGE, SELECT ON SEQUENCE pr_d_test.youtube_shorts_log_id_seq TO service_role;
